/* ============================================================
   Learner-language text (en, American English) for data/core/grammar-reference.js
   Keys point at ids in the neutral layer; arrays merge by index,
   so their length has to match core. Checked by scripts/parity.mjs.
   Cells in the learned language (German) carry class='it', the
   historical name of that field.

   Contrastive notes are written against English, not translated
   from another language: the point of comparison changes with the
   reader's language.
   ============================================================ */
LINGUAI.addStrings("en", {
  "refsec:titles": [
    "Nouns and articles",
    "Adjectives and adverbs",
    "Pronouns",
    "The verb",
    "Prepositions",
    "The sentence",
    "Pronunciation and register"
  ],
  "ref:g-genus": {
    title: "Noun gender",
    sub: "der, die, das",
    body: "<p>Every German noun is <b>masculine</b> (<em>der</em>), <b>feminine</b> (<em>die</em>) or <b>neuter</b> (<em>das</em>), objects included: <em>der Tisch, die Lampe, das Buch</em>. English has no grammatical gender, so there is no habit to lean on. The only reliable method is to learn every noun <b>with its article</b>, as one unit: not <em>Tisch</em>, but <em>der Tisch</em>.</p><h4>Cues that help</h4><ul><li><b>die</b>: <em>-ung, -heit, -keit, -schaft, -ion, -tät</em> (<em>die Zeitung, die Gesundheit, die Freundschaft, die Nation, die Universität</em>) and feminine <b>-in</b> (<em>die Lehrerin</em>).</li><li><b>das</b>: <em>-chen, -lein</em> (<em>das Mädchen, das Büchlein</em>). Diminutives are always neuter, even for a girl.</li><li><b>der</b>: nouns that name men specifically (<em>der Mann, der Lehrer</em>; but <em>das Kind</em> and <em>das Baby</em> are neuter even for a boy) and days, months, seasons (<em>der Montag, der Mai</em>).</li></ul><p class='callout callout--trap'><b>Trap:</b> gender is grammatical, not logical. <em>das Mädchen</em> (the girl) is neuter, and English <em>it</em> will not help you: a masculine noun is replaced by <em>er</em> even for a table (<em>Der Tisch ist neu. Er ist groß.</em>).</p>"
  },
  "ref:g-plural": {
    title: "The plural",
    sub: "-e, -er, -(e)n, -s, no ending, umlaut",
    body: "<p>English forms the plural almost always with <em>-s</em>. German has several patterns, and the plural article is <b>die</b> in the nominative and accusative, whatever the gender (the dative <em>den</em> comes later): <em>der Tisch → die Tische</em>, <em>das Kind → die Kinder</em>. Learn the plural together with the singular.</p><div class='table-wrap'><table class='gt'><thead><tr><th>pattern</th><th>singular</th><th>plural</th></tr></thead><tbody><tr><td>-e</td><td class='it'>der Tag</td><td class='it'>die Tage</td></tr><tr><td>-e + umlaut</td><td class='it'>die Stadt</td><td class='it'>die Städte</td></tr><tr><td>-er (+ umlaut)</td><td class='it'>das Kind, das Haus</td><td class='it'>die Kinder, die Häuser</td></tr><tr><td>-(e)n</td><td class='it'>die Frau, das Auge</td><td class='it'>die Frauen, die Augen</td></tr><tr><td>no ending</td><td class='it'>der Lehrer, die Mutter</td><td class='it'>die Lehrer, die Mütter</td></tr><tr><td>-s</td><td class='it'>das Auto, das Handy</td><td class='it'>die Autos, die Handys</td></tr></tbody></table></div><ul><li>Most feminine nouns take <b>-(e)n</b>; <b>-s</b> is rare and mostly for foreign words.</li><li>Only <b>a, o, u, au</b> take an umlaut: <em>der Vater → die Väter</em>.</li></ul><p class='callout callout--trap'><b>Trap:</b> English speakers over-apply <em>-s</em> (<em>*die Tags, *die Kinds</em>). Here <em>-s</em> is the exception, not the rule.</p>"
  },
  "ref:g-artikel-nom": {
    title: "Articles in the nominative",
    sub: "der/die/das/die, ein/eine/ein, kein/keine",
    body: "<p>The nominative is the case of the subject and of the noun after <em>sein</em>. English has one definite article, <em>the</em>; German has four forms, because it shows gender and number.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pl.</th></tr></thead><tbody><tr><td>the</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>a / an</td><td class='it'>ein</td><td class='it'>eine</td><td class='it'>ein</td><td>-</td></tr><tr><td>no / not a</td><td class='it'>kein</td><td class='it'>keine</td><td class='it'>kein</td><td class='it'>keine</td></tr></tbody></table></div><p>After <em>sein</em> a predicate noun is nominative: <em>Das ist der Kaffee. Er ist Arzt.</em> A predicate adjective takes no case ending: <em>Er ist müde.</em> <em>Ich bin in der Schule</em> is different: <em>in der Schule</em> is a prepositional phrase, not a nominative.</p><ul><li><b>Definite</b>: the thing is known or unique: <em>Der Kaffee ist heiß.</em></li><li><b>Indefinite</b>: it is new or one of many: <em>Das ist ein Kaffee.</em></li><li><b>kein</b> is <em>ein</em> with a <em>k-</em>: it negates a noun (see <em>g-negation</em>): <em>Ich habe keinen Hund.</em></li><li>The indefinite article has <b>no plural</b>, just like English: <em>Das sind Kinder.</em></li></ul><p class='callout callout--trap'><b>Note:</b> <em>ein</em> is also the number <em>one</em>, as in English <em>a / one</em>. With professions German drops the article: <em>Er ist Arzt</em> (He is a doctor).</p>"
  },
  "ref:g-artikel-akk": {
    title: "Articles in the accusative",
    sub: "only the masculine changes: den, einen, keinen",
    body: "<p>The accusative marks the <b>direct object</b>, the thing that is bought, eaten, seen. At A1 there is one rule to remember: <b>only the masculine singular changes</b>. Feminine, neuter and plural look exactly like the nominative.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pl.</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>der / ein / kein</td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / - / keine</td></tr><tr><td>accusative</td><td class='it'><b>den / einen / keinen</b></td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / - / keine</td></tr></tbody></table></div><ul><li><em>Der Kaffee ist gut.</em> → <em>Ich nehme <b>den</b> Kaffee.</em></li><li><em>Einen Kaffee, bitte.</em> (I would like a coffee.)</li><li><em>Ich habe <b>keinen</b> Hunger.</em> but <em>Ich habe <b>keine</b> Zeit.</em></li></ul><p class='callout callout--trap'><b>For English speakers:</b> English marks case only on pronouns (<em>he / him</em>). German marks it on the article of a noun, so the word order <em>Den Kaffee trinke ich</em> still tells you who drinks what. Check whether the noun is masculine before choosing the article.</p>"
  },
  "ref:g-artikel-dat": {
    title: "Articles in the dative",
    sub: "dem, der, dem, den + -n; einem, einer; meinem",
    body: "<p>The dative is the case used after certain prepositions (<em>mit, zu, bei, aus, von, nach, seit</em>) and, with two-way prepositions (<em>in, an, auf, unter, vor, hinter, neben, über, zwischen</em>), to say <em>where</em> something is (<em>in der Küche</em>); other prepositions govern their own case. Unlike the accusative, <b>every gender changes</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>the</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>den + <b>-n</b></td></tr><tr><td>a / an</td><td class='it'>einem</td><td class='it'>einer</td><td class='it'>einem</td><td>(none)</td></tr><tr><td>no / not a</td><td class='it'>keinem</td><td class='it'>keiner</td><td class='it'>keinem</td><td class='it'>keinen + <b>-n</b></td></tr><tr><td>possessive (mein, my)</td><td class='it'>meinem</td><td class='it'>meiner</td><td class='it'>meinem</td><td class='it'>meinen + <b>-n</b></td></tr></tbody></table></div><p>Examples: <em>Ich fahre mit dem Bus. Ich wohne bei meiner Schwester. Er kommt aus der Stadt.</em></p><p>In the plural the dative adds <b>-n</b> to the noun, unless the plural already ends in <em>-n</em> or <em>-s</em>: <em>die Kinder → mit den Kindern</em>, <em>die Freunde → mit den Freunden</em>, but <em>die Frauen → mit den Frauen</em> and <em>die Autos → mit den Autos</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> English nouns and articles look the same whatever job they do (<em>the man, with the man, to the man</em>); case survives only in pronouns (<em>he / him, we / us</em>). German keeps case on the <b>article</b> as well: <em>mit der Frau</em>, not <em>*mit die Frau</em>. Learn each preposition together with the case it asks for (<em>mit + Dativ</em>).</p><p>The prepositions that take the dative have their own entry. For now just recognize the form: after <em>mit</em> the masculine singular article is <em>dem</em>, not <em>den</em>: <em>mit dem Mann</em>.</p>"
  },
  "ref:g-adjektivdeklination": {
    title: "Predicate adjectives",
    sub: "Der Pullover ist rot: no ending",
    body: "<p>When the adjective comes after <em>sein</em> (or <em>werden, bleiben</em>) it stays <b>unchanged</b>: it does not agree with the noun in gender or number.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sentence</th></tr></thead><tbody><tr><td>masculine</td><td class='it'>Der Pullover ist rot.</td></tr><tr><td>feminine</td><td class='it'>Die Jacke ist rot.</td></tr><tr><td>neuter</td><td class='it'>Das Hemd ist rot.</td></tr><tr><td>plural</td><td class='it'>Die Schuhe sind rot.</td></tr></tbody></table></div><p>More examples: <em>Der Mantel ist teuer. Sie ist nett. Das Zimmer ist klein. Mein Bruder ist unfreundlich.</em> Also with <em>aussehen</em>: <em>Wie sieht er aus? Er sieht müde aus.</em></p><p class='callout callout--trap'><b>For English speakers:</b> this part will feel familiar, because English adjectives never change either (<em>the shoes are red</em>). The difference comes when the adjective stands <b>before the noun</b>: there German adjectives do take endings (<em>ein roter Pullover</em>), which English never does. Those endings come at later levels. For now use the adjective only after <em>sein</em>, with no ending: <em>Die Schuhe sind rot</em>, not <em>*roten</em> or <em>*rote</em>.</p><p>To ask what something is like: <em>Wie ist der Pullover?</em> Colors and other basic adjectives are in the vocabulary of units 4 and 8.</p>"
  },
  "ref:g-komparation": {
    title: "Comparative and superlative",
    sub: "-er ... als, so ... wie, am -sten",
    body: "<p>The comparative of superiority is formed with <b>-er</b>, the predicate superlative with <b>am ... -sten</b>. Comparisons of inequality use <b>als</b> (<em>than</em>; inferiority is <b>weniger ... als</b>, <em>weniger schön als</em>, without <b>-er</b>), equality uses <b>so ... wie</b> (<em>as ... as</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>base</th><th>comparative</th><th>superlative</th></tr></thead><tbody><tr><td class='it'>klein</td><td class='it'>kleiner</td><td class='it'>am kleinsten</td></tr><tr><td class='it'>schnell</td><td class='it'>schneller</td><td class='it'>am schnellsten</td></tr><tr><td class='it'>alt</td><td class='it'>älter</td><td class='it'>am ältesten</td></tr><tr><td class='it'>jung</td><td class='it'>jünger</td><td class='it'>am jüngsten</td></tr><tr><td class='it'>groß</td><td class='it'>größer</td><td class='it'>am größten</td></tr><tr><td class='it'>gut</td><td class='it'>besser</td><td class='it'>am besten</td></tr><tr><td class='it'>viel</td><td class='it'>mehr</td><td class='it'>am meisten</td></tr><tr><td class='it'>gern</td><td class='it'>lieber</td><td class='it'>am liebsten</td></tr></tbody></table></div><p>Examples: <em>Er ist größer als du. Sie ist so groß wie ich. Anna ist am größten. Ich trinke lieber Tee als Kaffee. Am liebsten trinke ich Wasser.</em></p><p>Many short adjectives take an <b>umlaut</b> (<em>alt, jung, groß</em>); <em>gut, viel, gern</em> have forms of their own and must be learned, as English does with <em>good, better, best</em> and <em>much, more, most</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>than</em> is <b>als</b> and <em>as ... as</em> is <b>so ... wie</b>: <em>bigger than you</em> is <em>größer als du</em>, <em>as big as you</em> is <em>so groß wie du</em>. Do not swap the two little words. German always adds <b>-er</b>, even on long adjectives: there is no <em>more + adjective</em> as in <em>more beautiful</em> (it is <em>schöner</em>). English has the article in the superlative (<em>the biggest</em>); here, referring to the subject of the sentence, German says <em>Er ist am größten</em>. <em>gern → lieber → am liebsten</em> has no single English adjective behind it: it corresponds to <em>like to, prefer, like best</em>.</p><p>Only the comparative as a predicate is shown here; before a noun (<em>der größere Bruder</em>) it comes later with the adjective endings.</p>"
  },
  "ref:g-possessiv": {
    title: "Possessives",
    sub: "mein, dein, sein, ihr, unser, euer, Ihr",
    body: "<p>You choose the possessive by the <b>owner</b>; it then takes the endings of <em>ein</em> according to the gender and case of the <b>thing owned</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>owner</th><th>possessive</th><th>English</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mein</td><td>my</td></tr><tr><td class='it'>du</td><td class='it'>dein</td><td>your</td></tr><tr><td class='it'>er</td><td class='it'>sein</td><td>his</td></tr><tr><td class='it'>sie (she)</td><td class='it'>ihr</td><td>her</td></tr><tr><td class='it'>es</td><td class='it'>sein</td><td>its</td></tr><tr><td class='it'>wir</td><td class='it'>unser</td><td>our</td></tr><tr><td class='it'>ihr</td><td class='it'>euer</td><td>your (plural)</td></tr><tr><td class='it'>sie (they)</td><td class='it'>ihr</td><td>their</td></tr><tr><td class='it'>Sie (formal)</td><td class='it'>Ihr</td><td>your (formal)</td></tr></tbody></table></div><p>Examples: <em>Meine Mutter heißt Anna. Mein Chef ist nett. Das ist unser Haus. Ich sehe meinen Bruder.</em> In the nominative and accusative, with feminine nouns and in the plural: <em>mein</em> + <b>-e</b> (<em>meine Mutter, meine Eltern</em>); in the dative it is <em>meiner Mutter, meinen Eltern</em>; masculine accusative: <em>meinen</em>. <em>euer</em> drops its <em>e</em> before an ending: <em>eure Mutter, euren Bruder</em>.</p><p>With first names the genitive is made with <b>-s</b>, with no apostrophe: <em>Annas Mutter, Peters Auto</em>. If the name ends in a sibilant (<em>-s, -x, -z, -ß</em>) you add only the apostrophe: <em>Hans’ Mutter, Max’ Auto</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the owner decides which word you use, exactly as in English: <em>seine Mutter</em> is <em>his mother</em>, <em>ihre Mutter</em> is <em>her mother</em>. What English lacks is the ending, which follows the <b>thing owned</b>, not the owner: <em>Er liebt seine Mutter</em> (feminine noun, so <em>-e</em>) but <em>Sie liebt ihren Vater</em> (masculine accusative, so <em>-en</em>). Remember too that <em>ihr</em> can mean <em>her</em> or <em>their</em>, and that there is no <em>’s</em>: <em>Annas Mutter</em> is <em>Anna’s mother</em>.</p><p>The formal <em>Ihr</em> is capitalized, like <em>Sie</em>: <em>Wie ist Ihr Name?</em></p>"
  },
  "ref:g-adverbien": {
    title: "Adverbs",
    sub: "sehr, zu, viel, wenig; immer, oft, manchmal, nie; gut",
    body: "<h4>Degree</h4><ul><li><b>sehr</b> (very) before an adjective: <em>Der Kaffee ist sehr gut.</em></li><li><b>zu</b> (too): <em>Die Hose ist zu klein.</em> <b>ziemlich</b> (fairly, quite), <b>ein bisschen</b> (a little).</li><li><b>viel</b> and <b>wenig</b> (a lot, little) after the verb: <em>Ich arbeite viel. Er schläft wenig.</em></li></ul><h4>Frequency</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th></tr></thead><tbody><tr><td class='it'>immer</td><td>always</td></tr><tr><td class='it'>oft</td><td>often</td></tr><tr><td class='it'>manchmal</td><td>sometimes</td></tr><tr><td class='it'>selten</td><td>rarely</td></tr><tr><td class='it'>nie</td><td>never</td></tr></tbody></table></div><p>They usually come after the verb: <em>Ich trinke immer Kaffee.</em> If one opens the sentence, the subject moves behind the verb: <em>Morgens trinke ich immer Kaffee.</em></p><h4>Manner</h4><p>The adjective, with no ending, doubles as the adverb: <em>Er spricht gut. Sie fährt schnell. Das Kind schläft ruhig.</em> <em>gern</em> (gladly) is an adverb too: <em>Ich lese gern.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English adds <em>-ly</em> or changes the word (<em>quick / quickly, good / well</em>); German uses the same word both times: <em>Der Kaffee ist gut</em> (is good) and <em>Er spricht gut</em> (speaks well). English frequency adverbs sit before the verb (<em>I always drink coffee</em>); in German the verb stays second and the adverb follows it. As in English, <b>sehr</b> goes with adjectives and adverbs (<em>very good</em>) and <b>viel</b> with quantity (<em>a lot of time, I sleep a lot</em>); <em>*viel gut</em> is wrong. <em>gern</em> has no direct English adverb: <em>Ich lese gern</em> is <em>I like reading</em> or <em>I like to read</em>. Like English <em>never</em>, <em>nie</em> already carries the negation: <em>Ich trinke nie Bier</em>, with no <em>nicht</em>.</p>"
  },
  "ref:g-personalpron": {
    title: "Personal pronouns",
    sub: "ich, du, er/sie/es, wir, ihr, sie, Sie",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th></th><th>singular</th><th>plural</th></tr></thead><tbody><tr><td>1st person</td><td class='it'>ich</td><td class='it'>wir</td></tr><tr><td>2nd person, informal</td><td class='it'>du</td><td class='it'>ihr</td></tr><tr><td>3rd person</td><td class='it'>er, sie, es</td><td class='it'>sie</td></tr><tr><td>formal (sing. and pl.)</td><td class='it' colspan='2'>Sie</td></tr></tbody></table></div><ul><li><b>ich</b> is not capitalised mid-sentence (<em>Heute bin ich müde</em>); <b>Sie</b> (formal you) always is.</li><li><b>er / sie / es</b> follow the noun's gender, not meaning: <em>der Tisch → er</em>, <em>die Lampe → sie</em>, <em>das Buch → es</em>.</li><li><b>sie</b> has three meanings: <em>she</em>, <em>they</em>, and the formal <em>Sie</em>. The verb separates the singular <em>sie kommt</em> (she) from the other two; <em>sie kommen</em> (they) and <em>Sie kommen</em> (you, formal) look and sound alike, so the capital letter in writing and the context in speech decide.</li></ul><p class='callout callout--trap'><b>For English speakers:</b> English <em>you</em> covers one person, many people, friends and strangers. German splits it in three: <em>du</em> (one friend), <em>ihr</em> (several friends), <em>Sie</em> (one or more strangers, formal, singular or plural). And the subject pronoun is obligatory in statements and questions: <em>Ich komme</em>, not <em>Komme</em>. The informal imperative omits it (<em>Komm! Kommt!</em>); the formal one keeps it (<em>Kommen Sie!</em>). Coordinated main clauses can also leave out a shared subject: <em>Ich gehe ins Kino und sehe einen Film.</em></p>"
  },
  "ref:g-pron-akk": {
    title: "Pronouns in the accusative",
    sub: "mich, dich, ihn, sie, es, uns, euch, sie, Sie",
    body: "<p>When the direct object is already known, you replace it with an accusative pronoun. <em>ich, du, er, wir, ihr</em> change; <em>sie, es</em> and <em>sie/Sie</em> stay the same as in the nominative.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominative</th><th>accusative</th><th>English</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td>I / me</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td>you / you</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td><td>he / him</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td>she / her</td></tr><tr><td class='it'>es</td><td class='it'>es</td><td>it / it</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td>we / us</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td>you / you (plural)</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td>they / them</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td><td>you / you (formal)</td></tr></tbody></table></div><p>For things the pronoun follows the <b>gender of the German noun</b>: <em>Was kostet der Pullover? Ich nehme ihn. Wie findest du die Jacke? Ich nehme sie. Das Hemd? Ich nehme es.</em> With people: <em>Ich sehe dich. Er ruft uns an. Ich liebe sie.</em></p><p class='callout callout--trap'><b>For English speakers:</b> you already know this idea from <em>he / him, we / us</em>, and the pronoun comes after the verb just as in English (<em>Ich nehme ihn</em>, <em>I take it</em>). Two things differ. English uses <em>it</em> for every thing, while German says <b>ihn / sie / es</b> according to the noun: <em>der Pullover</em> gives <em>ihn</em>, not <em>es</em>. And the pairs that stay unchanged are not the same ones: English keeps <em>you</em> and <em>it</em>, German keeps <em>sie, es, Sie</em>, so <em>du</em> and <em>ihr</em> do change (<em>dich, euch</em>). <em>Ich sehe sie</em> can be <em>I see her</em> or <em>I see them</em>; context decides.</p>"
  },
  "ref:g-indefinitpron": {
    title: "einer, eins, welche, keiner",
    sub: "pronouns that replace a noun already mentioned",
    body: "<p>To avoid repeating a noun you use forms of <em>ein</em>, <em>kein</em> and <em>welche</em> without the noun. The ending shows gender and case.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>plural</th></tr></thead><tbody><tr><td>nominative</td><td class='it'>einer</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>accusative</td><td class='it'>einen</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>negative (nom.)</td><td class='it'>keiner</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr><tr><td>negative (acc.)</td><td class='it'>keinen</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr></tbody></table></div><p>Examples: <em>Ich brauche einen Stuhl. Haben Sie einen? Ja, ich habe einen. Haben Sie Brötchen? Ja, wir haben welche. Nein, wir haben keine. Ein Bier? Ich nehme eins.</em></p><p>With a number the number is enough: <em>Ich nehme zwei.</em> <b>welche</b> replaces a plural noun that has already been mentioned: <em>Hast du Brötchen? Ja, ich habe welche.</em> (<em>Do you have rolls? Yes, I have some.</em>). The bare noun stays possible when you first name it: <em>Ich kaufe Brötchen.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English has <em>one</em>, <em>some</em> and <em>none</em> for this job, and they never change (<em>Do you have a brother? Yes, I have one</em>). German uses <b>einen</b> for <em>one</em>, <b>welche</b> for <em>some</em> and <b>keinen / keine</b> for <em>none</em>, and the ending agrees with the noun you leave out: <em>Hast du einen Bruder? Ja, ich habe einen.</em> For a neuter noun the form is <em>eins</em> (in written German also <em>eines</em>). In a short answer German still needs the pronoun: <em>Ja, ich habe welche</em>, not just <em>Ja, ich habe</em>. The fuller forms with <em>jemand, jeder, etwas</em> come at B1.</p>"
  },
  "ref:g-es": {
    title: "es gibt, es regnet, es geht",
    sub: "es with no meaning of its own",
    body: "<p>In many German sentences the subject <em>es</em> does not stand for anything, but it is needed: as a rule the sentence requires an expressed subject.</p><h4>es gibt (there is, there are)</h4><p>The form is <b>always singular</b>, and after <em>gibt</em> the noun goes in the <b>accusative</b>: <em>Es gibt einen Bahnhof. Es gibt keinen Supermarkt hier. Es gibt drei Kinos in der Stadt.</em> Question: <em>Gibt es hier ein Café?</em></p><h4>Weather, time, states</h4><ul><li><em>Es regnet. Es schneit. Es ist kalt. Es ist heiß.</em></li><li><em>Es ist Montag. Wie spät ist es? Es ist acht Uhr.</em></li><li><em>Wie geht’s? Es geht.</em></li></ul><p class='callout callout--trap'><b>For English speakers:</b> English needs a dummy subject too (<em>it rains, it’s cold, it’s Monday, what time is it?</em>), so <em>es</em> will feel natural there: you cannot leave it out (<em>Es regnet</em>, not <em>*Regnet</em>). The new thing is <b>es gibt</b>. <em>There is</em> and <em>there are</em> both become <em>es gibt</em>, and the verb never changes: <em>Es gibt drei Kinos</em>. German also keeps the two jobs apart: <em>es gibt</em> introduces something new (<em>Es gibt ein Café</em>), while for placing something already known you use <em>sein</em> (<em>Wo ist das Café? Es ist neben der Post.</em>). <em>Wie geht’s?</em> is <em>How’s it going?</em> and <em>Es geht</em> means roughly <em>so-so, I’m managing</em>.</p><p>Uses of <em>es</em> as a placeholder or as a pointer to a subordinate clause come much later.</p>"
  },
  "ref:g-praesens": {
    title: "The present tense",
    sub: "stem + -e, -st, -t, -en, -t, -en; sein, haben; vowel change",
    body: "<p>The present covers both <em>I drink</em> and <em>I am drinking</em>: German has <b>no regular progressive form</b> to learn at this level, so one tense does both jobs. <em>Ich trinke Kaffee</em> can mean either. It also works for the near future: <em>Morgen fahre ich nach Berlin.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>machen</th><th>sein</th><th>haben</th></tr></thead><tbody><tr><td>ich</td><td class='it'>mache</td><td class='it'>bin</td><td class='it'>habe</td></tr><tr><td>du</td><td class='it'>machst</td><td class='it'>bist</td><td class='it'>hast</td></tr><tr><td>er/sie/es</td><td class='it'>macht</td><td class='it'>ist</td><td class='it'>hat</td></tr><tr><td>wir</td><td class='it'>machen</td><td class='it'>sind</td><td class='it'>haben</td></tr><tr><td>ihr</td><td class='it'>macht</td><td class='it'>seid</td><td class='it'>habt</td></tr><tr><td>sie/Sie</td><td class='it'>machen</td><td class='it'>sind</td><td class='it'>haben</td></tr></tbody></table></div><ul><li>Regular stems in <b>-t / -d</b> add <b>-e-</b>: <em>du arbeitest, er arbeitet, ihr arbeitet</em>. Strong verbs whose stem vowel changes do not add it with <em>du</em> and <em>er/sie/es</em>: <em>du hältst, er hält; du lädst, er lädt</em>; <em>ihr</em> keeps the -e-: <em>ihr haltet, ihr ladet</em>. In verbs in <b>-eln</b> the <em>e</em> of the stem is usually dropped after <em>ich</em>: <em>sammeln → ich sammle</em>; in <b>-ern</b> it normally stays: <em>wandern → ich wandere</em>. <em>wir</em> and <em>sie/Sie</em> match the infinitive: <em>sammeln, wandern</em>.</li><li>Stems in <b>-s, -ß, -z</b> drop the <em>-s</em> of <em>-st</em>: <em>du heißt, du tanzt</em>.</li><li><b>Vowel change</b> in <em>du</em> and <em>er/sie/es</em> only: <em>e → i</em> (<em>essen: du isst, er isst; nehmen: du nimmst; sprechen: du sprichst</em>), <em>e → ie</em> (<em>sehen: du siehst</em>), <em>a → ä</em> (<em>fahren: du fährst</em>).</li><li><b>gern</b> adds <em>like to</em>: <em>Ich trinke gern Tee.</em></li></ul>"
  },
  "ref:g-modalverben": {
    title: "Modal verbs",
    sub: "können, wollen, müssen, möchte; the verbal bracket",
    body: "<p>Modals express ability (<em>können</em>), will (<em>wollen</em>), obligation (<em>müssen</em>) and polite wishes (<em>möchte</em>). They conjugate in their own way: with <em>können, wollen, müssen</em> the 1st and 3rd person singular are <b>identical and have no ending</b> (<em>ich kann, er kann</em>), much like English <em>I can, he can</em>. <em>möchte</em> is the exception: it has <em>-e</em> (<em>ich möchte, er möchte</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>wollen</th><th>müssen</th><th>möchten</th></tr></thead><tbody><tr><td>ich</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>du</td><td class='it'>kannst</td><td class='it'>willst</td><td class='it'>musst</td><td class='it'>möchtest</td></tr><tr><td>er/sie/es</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>wir</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr><tr><td>ihr</td><td class='it'>könnt</td><td class='it'>wollt</td><td class='it'>müsst</td><td class='it'>möchtet</td></tr><tr><td>sie/Sie</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr></tbody></table></div><p>The modal is in <b>second position</b> and the infinitive goes at the <b>end of the sentence</b>: <em>Ich kann heute nicht kommen. Ich muss um sieben aufstehen. Wir wollen am Samstag ins Kino gehen.</em> The modal and the infinitive form a <b>bracket</b> around the rest of the sentence.</p><p><em>möchte</em> is the Konjunktiv II form of <em>mögen</em>, commonly used for polite wishes and requests; at this level treat it as a ready-made formula: <em>Ich möchte einen Kaffee.</em> (the infinitive can be left out). In a restaurant <em>Ich hätte gern das Schnitzel</em> is also a fixed formula.</p><p class='callout callout--trap'><b>For English speakers:</b> the pattern <em>modal + bare infinitive</em> is the same as in <em>I can come</em>, but English keeps the infinitive right behind the modal and German sends it to the end. <em>I can go to the movies with you tonight</em> becomes <em>Ich kann heute Abend mit dir ins Kino gehen</em>, and <em>*Ich kann gehen heute Abend ins Kino</em> is an error. Also, <em>want to</em> and <em>have to</em> need <em>to</em> in English, but German has no <em>zu</em> after the modal: <em>Ich will gehen, Ich muss gehen.</em> <em>Ich will einen Kaffee</em> sounds blunt, like <em>I want a coffee</em>; for a polite request use <em>möchte</em>, close to <em>I would like</em>. <em>dürfen</em> and <em>sollen</em> come later.</p>"
  },
  "ref:g-trennbare-verben": {
    title: "Separable verbs",
    sub: "aufstehen: Ich stehe um sieben auf",
    body: "<p>Many verbs have a stressed prefix that, in a main clause, <b>detaches</b> and goes to the end of the sentence. The infinitive stays in one piece.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>present</th><th>meaning</th></tr></thead><tbody><tr><td class='it'>aufstehen</td><td class='it'>Ich stehe um sieben auf.</td><td>get up</td></tr><tr><td class='it'>einkaufen</td><td class='it'>Wir kaufen am Samstag ein.</td><td>shop, go shopping</td></tr><tr><td class='it'>anrufen</td><td class='it'>Ich rufe dich an.</td><td>call, phone</td></tr><tr><td class='it'>fernsehen</td><td class='it'>Er sieht abends fern.</td><td>watch TV</td></tr><tr><td class='it'>mitkommen</td><td class='it'>Kommst du mit?</td><td>come along</td></tr><tr><td class='it'>ankommen</td><td class='it'>Der Zug kommt um acht an.</td><td>arrive</td></tr></tbody></table></div><p>With a modal the verb is whole again, at the end: <em>Ich muss um sieben aufstehen. Ich möchte heute einkaufen.</em> The two parts enclose the sentence, like the bracket of the modal.</p><p class='callout callout--trap'><b>For English speakers:</b> English phrasal verbs are a useful analogy: <em>get up, call up, come along, turn on</em> are also a verb plus a small particle with its own meaning. But the English particle stays close to the verb (<em>I get up at seven</em>), while the German one jumps to the <b>very end</b> of the clause: <em>Ich stehe um sieben auf</em>. The stem also keeps its vowel change: <em>fernsehen → er sieht fern</em>, <em>einladen → er lädt ein</em>.</p><p>Common separable prefixes: <em>auf-, an-, ein-, mit-, aus-, fern-, zurück-</em>. They are always stressed: <em>’aufstehen, ’anrufen</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the <b>inseparable</b> prefixes (<em>be-, ver-, er-, ent-, ge-</em>) are unstressed and <b>never detach</b>: <em>besuchen → Ich besuche dich</em>, <em>verstehen → Ich verstehe das</em>, <em>bekommen → Er bekommt ein Geschenk</em>. Watch out: <em>bekommen</em> means <em>to get, to receive</em>, not <em>to become</em> (that is <em>werden</em>). The Partizip II takes no <em>ge-</em> (<em>besucht, verstanden, bekommen</em>). The prefixes <em>über-, um-, unter-, durch-</em> can go either way; they come later.</p>"
  },
  "ref:g-imperativ": {
    title: "The polite imperative",
    sub: "Gehen Sie geradeaus!",
    body: "<p>With <b>Sie</b> the imperative is formed with the <b>infinitive + Sie</b>: the verb comes first and the pronoun right after it.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitive</th><th>imperative</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie geradeaus!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie die erste Straße links!</td></tr><tr><td class='it'>abbiegen</td><td class='it'>Biegen Sie rechts ab!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie bitte!</td></tr><tr><td class='it'>entschuldigen</td><td class='it'>Entschuldigen Sie, wo ist der Bahnhof?</td></tr></tbody></table></div><p>Separable verbs send the prefix to the end: <em>Biegen Sie rechts ab. Steigen Sie hier aus.</em> Exception: <em>sein</em> makes <b>Seien Sie</b> (<em>Seien Sie bitte pünktlich!</em>), not <em>*Sind Sie</em>. For directions you also need <em>geradeaus, links, rechts, die erste, die zweite Straße</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> an English command is just the bare verb (<em>Go straight ahead!</em>), with no <em>you</em>. German keeps the pronoun in the polite form: <em>Gehen Sie!</em>, verb first, then <em>Sie</em> (the only exception is <em>sein</em>: <em>Seien Sie!</em>). This also means the command has the same word order as a yes/no question: <em>Gehen Sie geradeaus!</em> or <em>Gehen Sie geradeaus?</em> English separates them with <em>do</em> (<em>Do you go straight?</em>), but German has no <em>do</em>: context, intonation and, in writing, punctuation tell them apart. A polite request can also end with a period, not only an exclamation mark.</p><p>The forms for <em>du</em> and <em>ihr</em> come at the next level.</p>"
  },
  "ref:g-perfekt": {
    title: "The Perfekt",
    sub: "haben/sein + Partizip II",
    body: "<p>In speech the past is formed with the <b>Perfekt</b>: the auxiliary (<em>haben</em> or <em>sein</em>) in second position and the <b>Partizip II</b> at the end of the sentence.</p><p><em>Ich habe gegessen. Wir haben einen Film gesehen. Ich bin nach Berlin gefahren. Sie ist früh aufgestanden.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>infinitive</th><th>Partizip II</th></tr></thead><tbody><tr><td>regular: ge- ... -t</td><td class='it'>machen</td><td class='it'>gemacht</td></tr><tr><td></td><td class='it'>kaufen</td><td class='it'>gekauft</td></tr><tr><td>strong: ge- ... -en</td><td class='it'>essen</td><td class='it'>gegessen</td></tr><tr><td></td><td class='it'>sehen</td><td class='it'>gesehen</td></tr><tr><td>with sein</td><td class='it'>fahren</td><td class='it'>gefahren</td></tr><tr><td></td><td class='it'>gehen</td><td class='it'>gegangen</td></tr><tr><td></td><td class='it'>kommen</td><td class='it'>gekommen</td></tr><tr><td>separable: ge- in the middle</td><td class='it'>aufstehen</td><td class='it'>aufgestanden</td></tr><tr><td></td><td class='it'>einkaufen</td><td class='it'>eingekauft</td></tr><tr><td>no ge-</td><td class='it'>studieren</td><td class='it'>studiert</td></tr><tr><td></td><td class='it'>besuchen</td><td class='it'>besucht</td></tr></tbody></table></div><p>The participles of strong verbs must be learned together with the infinitive (<em>trinken, getrunken; schreiben, geschrieben</em>), much like English <em>drink, drunk; write, written</em>. Verbs in <em>-ieren</em> and verbs with an inseparable prefix (<em>be-, ver-, er-</em>) take no <em>ge-</em>.</p><p>You use <b>sein</b> with intransitive verbs of <b>change of place or state</b> (<em>fahren, gehen, kommen, fliegen, aufstehen</em>) and with <em>sein, bleiben, werden, passieren</em>; with almost all other verbs you use <b>haben</b>. When a motion verb is used transitively, with an accusative direct object, it generally takes <em>haben</em>: <em>Ich habe das Auto gefahren.</em> A dative object does not force <em>haben</em>: <em>Ich bin ihm gefolgt.</em> For <em>sein</em> and <em>haben</em> themselves, <em>war</em> and <em>hatte</em> are preferred: <em>Ich war in Berlin.</em></p><p class='callout callout--trap'><b>For English speakers:</b> the Perfekt looks like the English present perfect (<em>I have eaten</em> = <em>Ich habe gegessen</em>), but in speech it is the <b>ordinary past tense</b>. <em>Gestern habe ich einen Film gesehen</em> means <em>Yesterday I saw a movie</em>; English would not say <em>*Yesterday I have seen</em>. Two more differences: the participle goes at the <b>end of the clause</b> (<em>Wir haben gestern einen Film gesehen</em>), and the auxiliary is not always <em>have</em>: <em>I have gone</em> is <em>Ich bin gegangen</em>. Check the verb.</p>"
  },
  "ref:g-praep-akk": {
    title: "Prepositions with the accusative",
    sub: "für, ohne, um, durch, gegen",
    body: "<p>These prepositions always take the <b>accusative</b>, so only the masculine changes (<em>den, einen, keinen, meinen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>für</td><td>for</td><td class='it'>Das Geschenk ist für den Lehrer.</td></tr><tr><td class='it'>ohne</td><td>without</td><td class='it'>Ich trinke Kaffee ohne Zucker.</td></tr><tr><td class='it'>um</td><td>around; at (clock times)</td><td class='it'>Wir gehen um die Ecke. Um acht Uhr.</td></tr><tr><td class='it'>durch</td><td>through</td><td class='it'>Wir gehen durch den Park.</td></tr><tr><td class='it'>gegen</td><td>against; around (approximate time)</td><td class='it'>Ich bin gegen den Plan.</td></tr></tbody></table></div><p>With pronouns: <em>für mich, für dich, für ihn, ohne sie, gegen uns</em>. A useful phrase for the city: <em>Gehen wir ins Kino?</em> (<em>ins</em> = <em>in das</em>; the use of <em>in</em> with movement comes later).</p><p class='callout callout--trap'><b>For English speakers:</b> English nouns do not change after a preposition (<em>for the man</em>); only pronouns do (<em>for him</em>). German does the same with pronouns (<em>für ihn</em>) but also marks the case on the masculine article: <em>für den Mann</em>, <em>für einen Freund</em>, not <em>*für der Mann</em>. With <em>ohne</em> before a mass noun the article is normally left out, as in English (<em>ohne Zucker, ohne Milch</em>).</p>"
  },
  "ref:g-praep-dativ": {
    title: "Prepositions with the dative",
    sub: "mit, zu, bei, aus, von, nach, seit",
    body: "<p>These seven prepositions always take the <b>dative</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>mit</td><td>with; by (means of transport)</td><td class='it'>Ich fahre mit dem Bus.</td></tr><tr><td class='it'>zu</td><td>to (a person or a place)</td><td class='it'>Ich gehe zum Bahnhof. Wir gehen zur Schule.</td></tr><tr><td class='it'>bei</td><td>at (someone’s place), near</td><td class='it'>Ich wohne bei meiner Tante. Er ist beim Arzt.</td></tr><tr><td class='it'>aus</td><td>from (origin), out of</td><td class='it'>Ich komme aus Italien.</td></tr><tr><td class='it'>von</td><td>from (starting point), of, by</td><td class='it'>Der Brief ist von meiner Mutter.</td></tr><tr><td class='it'>nach</td><td>to (cities and countries without an article); after</td><td class='it'>Ich fahre nach Berlin. Wir fliegen nach Italien. Nach dem Essen.</td></tr><tr><td class='it'>seit</td><td>since, for (with a duration)</td><td class='it'>Ich wohne seit einem Jahr hier.</td></tr></tbody></table></div><p>Many prepositions merge with the article: <b>zu dem → zum</b>, <b>zu der → zur</b>, <b>bei dem → beim</b>, <b>von dem → vom</b>. <em>Gehen Sie zum Bahnhof. Er ist beim Friseur. Ich komme vom Bahnhof.</em> English has no such contractions, so learn them as single words.</p><p class='callout callout--trap'><b>For English speakers:</b> <em>by bus</em> is <b>mit dem Bus</b>: German uses <em>mit</em> and an article. <em>to</em> splits three ways: <em>zu</em> (<em>zum Arzt, zum Bahnhof</em>), <em>nach</em> (<em>nach Berlin</em>) and, for countries that have an article, <em>in</em> + accusative (<em>in die Schweiz, in die Türkei, in die USA</em>), a contrast to know, not to use yet. <em>from</em> splits too: <em>aus</em> for origin (<em>Ich komme aus Rom</em>) and <em>von</em> for a starting point (<em>vom Bahnhof</em>). And with <em>seit</em> German uses the <b>present tense</b> where English uses the present perfect: <em>Ich wohne seit einem Jahr hier</em> is <em>I have lived here for a year</em>. Some fixed phrases: <em>zu Fuß</em> (on foot), <em>nach Hause</em> (home, as in <em>I’m going home</em>), <em>zu Hause</em> (at home).</p>"
  },
  "ref:g-wechselpraep": {
    title: "Prepositions with dative or accusative",
    sub: "wo? with the dative: in, an, auf, vor, hinter, neben, ...",
    body: "<p>Nine prepositions can take either the dative or the accusative. For now you only see the answer to <b>wo?</b> (where? position, location), which takes the <b>dative</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>in</td><td>in, inside</td><td class='it'>Ich bin in der Küche. Er wohnt in der Stadt.</td></tr><tr><td class='it'>an</td><td>on (a wall, an edge); at</td><td class='it'>Das Bild hängt an der Wand. Ich sitze am Fenster.</td></tr><tr><td class='it'>auf</td><td>on, on top of</td><td class='it'>Das Buch liegt auf dem Tisch.</td></tr><tr><td class='it'>vor</td><td>in front of</td><td class='it'>Der Bus hält vor dem Hotel.</td></tr><tr><td class='it'>hinter</td><td>behind</td><td class='it'>Der Bahnhof ist hinter dem Rathaus.</td></tr><tr><td class='it'>neben</td><td>next to</td><td class='it'>Das Café ist neben der Post.</td></tr><tr><td class='it'>über</td><td>above, over (no contact)</td><td class='it'>Die Lampe hängt über dem Tisch.</td></tr><tr><td class='it'>unter</td><td>under</td><td class='it'>Die Katze schläft unter dem Tisch.</td></tr><tr><td class='it'>zwischen</td><td>between</td><td class='it'>Das Kino ist zwischen der Bank und dem Park.</td></tr></tbody></table></div><p>Contractions: <b>in dem → im</b>, <b>an dem → am</b>: <em>Ich bin im Park. Wir sind am Bahnhof.</em> Question: <em>Wo ist der Bahnhof? Hinter dem Rathaus.</em></p><p class='callout callout--trap'><b>For English speakers:</b> English sometimes marks the difference between location and movement with a different word (<em>in / into, on / onto</em>); German uses the <b>same preposition</b> and changes the case: <em>in der Küche</em> (dative) is where you <em>are</em>, while movement into the place (<em>in die Küche</em>, accusative) comes at A2. For now ask yourself <em>wo?</em>, then use the dative. Also, English <em>on</em> covers two German words: <em>auf dem Tisch</em> (on top of) and <em>an der Wand</em> (on a vertical surface, hanging). <em>an</em> is also <em>at</em>: <em>am Fenster, am Bahnhof</em>.</p>"
  },
  "ref:g-temporalangaben": {
    title: "Time, days, months and dates",
    sub: "um, am, im; von ... bis, vor, seit",
    body: "<h4>The time</h4><p><em>Wie spät ist es?</em> / <em>Wie viel Uhr ist es?</em> Answer: <em>Es ist acht Uhr.</em> For a precise time: <em>Um acht Uhr.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>time</th></tr></thead><tbody><tr><td>7:00</td><td class='it'>Es ist sieben Uhr.</td></tr><tr><td>7:15</td><td class='it'>Es ist Viertel nach sieben.</td></tr><tr><td>7:30</td><td class='it'>Es ist <b>halb acht</b>.</td></tr><tr><td>7:45</td><td class='it'>Es ist Viertel vor acht.</td></tr><tr><td>7:10</td><td class='it'>Es ist zehn nach sieben.</td></tr><tr><td>7:50</td><td class='it'>Es ist zehn vor acht.</td></tr></tbody></table></div><p class='callout callout--trap'><b>For English speakers:</b> <b><em>halb acht</em> is half past seven</b>, not half past eight: German counts toward the hour that is coming, while English <em>half past seven</em> counts from the hour that has just gone by. This is the most common trap. <em>Viertel nach / Viertel vor</em> work like <em>quarter past / quarter to</em>, and <em>zehn nach / zehn vor</em> like <em>ten past / ten to</em>.</p><h4>Prepositions of time</h4><ul><li><b>um</b> + clock time: <em>um acht Uhr</em> (at eight)</li><li><b>am</b> + day, part of the day, date: <em>am Montag, am Abend, am 3. Mai</em> (but <em>in der Nacht</em>)</li><li><b>im</b> + month, season: <em>im Januar, im Sommer</em></li><li><b>von ... bis</b>: <em>von Montag bis Freitag, von acht bis vier</em></li><li><b>vor</b> (ago) and <b>seit</b> (since) + dative: <em>vor einer Woche, seit Montag</em></li></ul><p>The days: <em>Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag</em>. With <b>-s</b> you say that something happens every time: <em>montags, morgens, abends</em> (on Mondays, in the mornings, in the evenings). Dates use the ordinal, as in English <em>May 3rd</em>: <em>am ersten, zweiten, dritten, vierten Mai</em>; written <em>am 1. Mai</em>.</p><p class='callout callout--trap'><b>For English speakers:</b> the prepositions do not map one to one. <em>in the evening</em> is <em>am Abend</em> (not <em>in</em>), while <em>at night</em> is <em>in der Nacht</em>; <em>on Monday</em> is <em>am Montag</em> and <em>in January</em> is <em>im Januar</em>. <em>ago</em> goes <b>before</b> the noun: <em>a week ago</em> is <em>vor einer Woche</em>. And, as with <em>seit</em> above, German uses the present tense where English uses the present perfect: <em>seit Montag</em> in <em>Ich bin seit Montag hier</em> is <em>I have been here since Monday</em>.</p>"
  },
  "ref:g-satz-v2": {
    title: "Verb in second position",
    sub: "V2, inversion, questions",
    body: "<p>In a German declarative main clause the <b>conjugated verb is always the second element</b>. The first position can be the subject, but also a time or place word. English keeps subject-verb-object almost always; German keeps only the verb fixed.</p><ul><li><em>Ich gehe heute ins Kino.</em></li><li><em>Heute <b>gehe</b> ich ins Kino.</em> (the subject moves behind the verb: <b>inversion</b>)</li></ul><p class='callout callout--trap'><b>For English speakers:</b> the English order <em>Today I go</em> does not carry over: <em>*Heute ich gehe</em> is wrong. German says <em>Heute gehe ich</em>, with the verb still in second place: time word first, then the verb, then the subject.</p><h4>Questions</h4><ul><li><b>W-questions</b>: question word, then the verb: <em>Wo wohnst du? Was trinkst du? Wann kommt er?</em></li><li><b>Yes/no questions</b>: the verb goes <b>first</b>: <em>Kommst du aus Berlin? Hast du Zeit?</em></li></ul><p>German has no <em>do</em>-support: not <em>*Machst du trinken?</em>. You simply move the verb: <em>Trinkst du Kaffee?</em> Words like <em>und, aber, oder</em> do not count as a position, so the verb is still second after them.</p>"
  },
  "ref:g-negation": {
    title: "Negation: nicht and kein",
    sub: "nicht vs kein, position, doch",
    body: "<p>German has two negators, where English uses <em>not</em> and <em>no</em>.</p><ul><li><b>kein</b> negates a <b>noun with an indefinite article or no article</b>: <em>Ich habe einen Hund → Ich habe keinen Hund. Ich habe Zeit → Ich habe keine Zeit.</em> It takes the endings of <em>ein</em> (<em>keinen, keine, kein</em>).</li><li><b>nicht</b> negates <b>everything else</b>: verbs, adjectives, adverbs, nouns with a definite article: <em>Ich komme nicht. Das ist nicht gut. Ich nehme den Kaffee nicht.</em></li></ul><h4>Position of nicht</h4><ul><li>In a simple sentence it goes at the <b>end</b> when the whole sentence is negated: <em>Ich kenne ihn nicht.</em> If the sentence ends in an infinitive or a separable particle, <em>nicht</em> comes before that final verb part; its exact position depends on what is negated, and other complements may stand in between: <em>Ich kann nicht kommen. Ich kann nicht nach Berlin kommen. Ich rufe ihn nicht an. Ich rufe nicht jeden Tag an.</em></li><li>Placement is a tendency, not a fixed rule: it usually goes <b>before</b> an adjective, adverb, destination or predicate: <em>Das ist nicht teuer. Er wohnt nicht hier.</em></li></ul><h4>doch</h4><p>To contradict a negative question or statement, German uses <b>doch</b> where English says <em>yes</em>: <em>Kommst du nicht? - Doch, ich komme!</em> (Yes, I am coming.) <em>Doch</em> contradicts the negation explicitly. To confirm it, say <em>Nein, ich komme nicht</em>; a bare <em>ja</em> can be ambiguous.</p><p class='callout callout--trap'><b>For English speakers:</b> there is no <em>do not</em>. <em>I don't drink coffee</em> is <em>Ich trinke keinen Kaffee</em>, while <em>Ich trinke den Kaffee nicht</em> means <em>I'm not drinking the coffee</em> (that particular one); the verb never changes shape.</p>"
  },
  "ref:g-konnektoren": {
    title: "Linking clauses: und, aber, oder, denn",
    sub: "position zero: the word order does not change",
    body: "<p>These four conjunctions link two main clauses and stand in <b>position zero</b>: they do not count as the first element and they do not change the order of their clause: the verb stays in <b>second position</b> in statements and in <b>first position</b> in yes/no questions (<em>Gehen wir ins Kino, oder bleiben wir zu Hause?</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>meaning</th><th>example</th></tr></thead><tbody><tr><td class='it'>und</td><td>and</td><td class='it'>Ich gehe ins Kino, und er bleibt zu Hause.</td></tr><tr><td class='it'>aber</td><td>but</td><td class='it'>Ich bin müde, aber ich gehe ins Kino.</td></tr><tr><td class='it'>oder</td><td>or</td><td class='it'>Gehen wir ins Kino, oder bleiben wir zu Hause?</td></tr><tr><td class='it'>denn</td><td>because, for (gives the reason)</td><td class='it'>Ich bleibe zu Hause, denn ich bin müde.</td></tr></tbody></table></div><p>In a clause that starts with the subject, the subject stays before the verb; if the second clause has another element in front, the verb keeps its position anyway: <em>Ich arbeite, aber am Samstag habe ich frei.</em> If the subject is the same it can be left out after <b>und, oder, aber</b>: <em>Ich gehe ins Kino und sehe einen Film.</em> Not after <b>denn</b>: the subject is repeated (<em>Ich bleibe zu Hause, denn ich bin müde</em>).</p><p>Before <b>aber</b> and <b>denn</b> the comma is required; before <b>und</b> and <b>oder</b> it is optional between two main clauses.</p><p class='callout callout--trap'><b>For English speakers:</b> after <em>but</em> English keeps subject-then-verb (<em>but on Saturday I’m off</em>), whereas German puts the verb second even after a time phrase, so the subject moves behind it: <em>aber am Samstag habe ich frei</em>. German also requires the comma before <em>aber</em> and <em>denn</em>, which English often leaves out. <em>because</em> has two German equivalents: <b>denn</b> gives the reason and does <b>not</b> move the verb (<em>denn ich bin müde</em>); it introduces the reason for a preceding statement and keeps main-clause order, and it can start a new sentence (<em>Ich bleibe zu Hause. Denn ich bin müde.</em>); <b>weil</b>, which sends the verb to the end, comes at A2. For now, to give a reason write <em>denn</em> and leave the verb where it is.</p>"
  },
  "ref:g-aussprache": {
    title: "Pronunciation",
    sub: "ä ö ü, ß, ch, sch, sp/st, w, v, z, ei/ie, eu/äu",
    body: "<p>German spelling is far more regular than English: each letter or letter group has one main sound. A few letters are silent or only mark length: the <em>h</em> in <em>sehen, fahren</em> is not pronounced, it shows that the vowel is long.</p><ul><li><b>ä</b> is short like <em>e</em> in <em>bed</em> in <em>hätte</em>, and long in <em>Käse</em> (many speakers say it like a long <em>e</em>); <b>ö</b>: for long <em>ö</em> (<em>schön</em>) hold a steady <em>eh</em> vowel (no glide, unlike English <em>say</em>) and round your lips; in <em>können</em> it is a short rounded vowel; <b>ü</b> as <em>ee</em> with rounded lips: long in <em>über</em> [yː], short in <em>müssen, fünf</em> [ʏ], where it is shorter and more open but still rounded. English has no ö and ü: practice them in minimal pairs.</li><li><b>ß</b> is a sharp <em>s</em> and stands after a long vowel or diphthong (<em>heißen, Straße</em>); after a short vowel you write <em>ss</em> (<em>müssen</em>). <em>ss</em> replaces <em>ß</em> only where the character is not available.</li><li><b>ch</b> is voiceless and soft [ç] after front vowels and consonants (<em>ich, Milch</em>, like the <em>h</em> in <em>hue</em>), back [x] after <em>a, o, u, au</em> (<em>ach, Buch</em>). In some loans it is [k] (<em>Chor, Charakter</em>). <em>chs</em> is [ks] only when the <em>s</em> belongs to the stem (<em>wachsen, sechs</em>); with an ending <em>ch</em> keeps its sound (<em>machst</em> [xst], <em>höchste</em> [çst]). Final <b>-ig</b> is [ɪç] (<em>König, richtig</em>).</li><li><b>sch</b> = English <em>sh</em> (<em>Schule</em>); <b>sp-</b> and <b>st-</b> at the start of a word are <em>shp-, sht-</em> (<em>sprechen, Stadt</em>).</li><li><b>w</b> = English <em>v</em> (<em>Wasser</em>); <b>v</b> is usually English <em>f</em> (<em>Vater, viel</em>), but [v] in many loans (<em>Vase, Video</em>); <b>z</b> = <em>ts</em> (<em>Zeit</em>).</li><li><b>ei</b> = <em>eye</em> (<em>mein</em>); <b>ie</b> = long <em>ee</em> (<em>Brief</em>); <b>eu / äu</b> = <em>oy</em> (<em>neu, Häuser</em>).</li></ul><p><b>Final devoicing:</b> <em>b, d, g</em> at the end of a syllable are <em>p, t, k</em> (<em>Tag, Hand, ab</em>), except in the ending <em>-ig</em> (see above). <b>Stress</b> usually falls on the first syllable: <em>ARbeit, MORgen</em>.</p><p class='callout callout--trap'><b>Trap:</b> do not read German <em>w</em> and <em>v</em> as in English: <em>Wasser</em> starts with an English <em>v</em>, <em>Vater</em> with an <em>f</em>. German <em>th</em> never has the English [θ]/[ð] sound: in compounds like <em>Rathaus</em> you say <em>t</em> and <em>h</em> separately, and in words like <em>Theater</em> and <em>Thema</em> the group is just [t].</p>"
  },
  "ref:g-register": {
    title: "du and Sie, greetings",
    sub: "du / Sie, times of day, Tschüss / Auf Wiedersehen",
    body: "<p>German has two ways of saying <em>you</em> to one person, and the choice shows respect, not only grammar.</p><ul><li><b>du</b>: friends, family, children, peers and usually colleagues in informal workplaces. Plural: <em>ihr</em>.</li><li><b>Sie</b>: strangers, customers, officials, older people you do not know, and business contexts. Same form for one or many. Always capitalised; the verb is third person plural: <em>Wie heißen Sie?</em></li></ul><p>When in doubt, start with <em>Sie</em>. The switch to <em>du</em> is offered by the older or higher-ranking person (<em>Wir können uns duzen</em>); do not switch on your own.</p><h4>Greetings by time of day</h4><ul><li><em>Guten Morgen</em> (until about 10), <em>Guten Tag</em> (the whole day), <em>Guten Abend</em> (from the evening), <em>Gute Nacht</em> (when going to bed or saying goodbye late at night).</li><li><em>Hallo</em> and <em>Hi</em> are informal; <em>Wie geht's?</em> is common in informal exchanges, but asking how someone is is not an automatic greeting for everyone; with people you address as <em>Sie</em> use <em>Wie geht es Ihnen?</em>. The explicit pair is <em>Wie geht es dir?</em> (du) and <em>Wie geht es Ihnen?</em> (Sie).</li></ul><h4>Saying goodbye</h4><ul><li><em>Auf Wiedersehen</em> (formal), <em>Tschüss</em> (informal), <em>Bis später / Bis morgen</em>.</li></ul><h4>Regional greetings (for recognition)</h4><ul><li><em>Grüß Gott</em> (south Germany, Austria) and <em>Moin</em> (north, any time of day) are greetings, not goodbyes. <em>Servus</em> (Bavaria, Austria) works both ways.</li></ul><p class='callout callout--trap'><b>For English speakers:</b> English <em>you</em> hides the difference, so a wrong choice is easy. A greeting like <em>Hi</em> to a customer would sound too casual; <em>Guten Tag</em> is always safe.</p>"
  }
});
